import heapq


def _dependency_solver(preference, name_order):
    def solve(data):
        packages = data["packages"]
        roots = data["roots"]
        names = sorted(packages, reverse=(name_order == "descending"))
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        domains = []
        for name in names:
            versions = [row["version"] for row in packages[name]
                        if row["version"] not in blocked.get(name, [])
                        and (name not in pins or row["version"] == pins[name])]
            domains.append([None] + versions)

        best_vector = None
        best_versions = None
        for values in product(*domains):
            selected = {name: version for name, version in zip(names, values)
                        if version is not None}
            if any(name not in selected or not bounds[0] <= selected[name] <= bounds[1]
                   for name, bounds in roots.items()):
                continue

            edges = {}
            valid = True
            for name, version in selected.items():
                row = next(row for row in packages[name] if row["version"] == version)
                deps = [dep for dep in row.get("deps", [])
                        if not dep.get("feature") or dep["feature"] in features]
                edges[name] = []
                for dep in deps:
                    other = dep["name"]
                    if (other not in selected
                            or not dep["min"] <= selected[other] <= dep["max"]):
                        valid = False
                        break
                    edges[name].append(other)
                if not valid:
                    break
            if not valid:
                continue

            visiting, finished = set(), set()
            def acyclic(name):
                if name in visiting:
                    return False
                if name in finished:
                    return True
                visiting.add(name)
                if any(not acyclic(other) for other in edges[name]):
                    return False
                visiting.remove(name)
                finished.add(name)
                return True
            if not all(acyclic(name) for name in selected):
                continue

            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name not in reachable:
                    reachable.add(name)
                    stack.extend(edges[name])
            if reachable != set(selected):
                continue

            vector = tuple(-1 if value is None else value for value in values)
            if (best_vector is None
                    or (vector > best_vector if preference == "maximum"
                        else vector < best_vector)):
                best_vector = vector
                best_versions = selected

        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    half_up = data["rounding"] == "half_up"
    def rounded(n, d):
        return (n + d // 2) // d if half_up else n // d

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(net * event.get("tax_bp", 0), 10000)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    available = [j for j in jobs if j["id"] not in blocked]
    best_value = None
    best_ids = None

    for chosen in product((0, 1), repeat=len(available)):
        selected = [job for job, take in zip(available, chosen) if take]
        if len(selected) != k:
            continue
        ids = {job["id"] for job in selected}
        if not mandatory <= ids:
            continue
        counts = {}
        for job in selected:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        active = []
        okay = True
        for job in sorted(selected, key=lambda j: (j["start"], j["end"])):
            active = [end for end in active if end > job["start"]]
            active.append(job["end"])
            if len(active) > 2:
                okay = False
                break
        if not okay:
            continue

        value = sum(job["value"] for job in selected)
        sorted_ids = tuple(sorted(ids))
        if (best_value is None or value > best_value
                or (value == best_value and sorted_ids < best_ids)):
            best_value, best_ids = value, sorted_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit.get(source, 0)
    start = data["start"]
    initial = (source, initial_mask, data["coupons"])
    distances = {initial: start}
    queue = [(start, source, initial_mask, data["coupons"])]

    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}

        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(2, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            next_mask = mask | bit.get(edge["v"], 0)
            for duration, next_remaining in options:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, next_remaining)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, edge["v"], next_mask, next_remaining))
    return {"arrival": None}


